 56 |     // Helper function to map array of DB Transactions to BFF Transactions
 57 |     private mapDBTransactionsToBFF(dbTransactions: Transaction[]): BFFTransaction[] {
 58 |         return dbTransactions.map(mapDBTransactionToBFF);
 59 |     }
