201 |         const holding = await this.holdingRepository.findById(holdingId);
202 | 
203 |         if (!holding) {
204 |             throw new Error('Holding not found');
205 |         }
206 | 
207 |         const portfolio = await this.portfolioRepository.findById(holding.portfolio_id);
208 | 
